 $('#profitSales').innerHTML=ss.length?'<div class="table-wrap"><table><thead><tr><th>DATE</th><th>METHOD</th><th>BUYER</th><th>EGG SIZE</th><th>QUANTITY</th><th>TOTAL</th><th>ACTIONS</th></tr></thead><tbody>'+sorted(ss).map(r=>'<tr><td>'+esc(rowDate(r))+'</td><td>'+(r.data.selling_method==='tray'?'Tray sale':'Individual eggs')+'</td><td>'+esc(r.data.buyer||'No Buyer Information Yet')+'</td><td>'+esc(r.data.item||'—')+'</td><td>'+(r.data.selling_method==='tray'?trayQuantityLabel(r.data):num(r.data.quantity)+' eggs')+'</td><td><b>'+money(r.data.total)+'</b></td><td>'+actionsCell(r)+'</td></tr>').join('')+'</tbody></table></div>':noData('No sales in this date range.');
