function wireForm(k){
 const form=$('#recordForm');
 if(k==='harvest'){const update=()=>{$('#liveEggTotal').textContent=SIZES.reduce((a,s)=>a+Math.max(0,num(form.elements['q_'+s].value)),0).toLocaleString()};SIZES.forEach(s=>form.elements['q_'+s].addEventListener('input',update));update()}
 if(k==='sale'){const update=()=>$('#saleTotal').textContent=money(num(form.elements.quantity.value)*num(form.elements.price.value));form.elements.quantity.addEventListener('input',update);form.elements.price.addEventListener('input',update);update()}
 if(k==='tray_sale'){
  const itemSelect=form.querySelector('[name="item"]');
  const update=()=>{const full=Math.max(0,Math.floor(num(form.elements.full_tray_quantity.value))),half=form.elements.include_half_tray.checked,fullPrice=trayPrice(itemSelect.value,1),halfPrice=trayPrice(itemSelect.value,0.5),capacity=num(settings.tray_capacity)||30,total=full*fullPrice+(half?halfPrice:0);$('#trayPreviewSize').textContent=itemSelect.value;$('#trayPreviewEggs').textContent=((full+(half?0.5:0))*capacity).toLocaleString();$('#fullTrayPrice').textContent=money(fullPrice);$('#halfTrayPrice').textContent=money(halfPrice);$('#trayTotal').textContent=money(total)};
  itemSelect.addEventListener('change',update);
  form.elements.full_tray_quantity.addEventListener('input',update);
  form.elements.include_half_tray.addEventListener('change',update);
  update();
 }
 if(k==='expense'){
  const update=()=>form.elements.amount.value=money(num(form.elements.quantity.value)*num(form.elements.price.value));
  form.elements.quantity.addEventListener('input',update);form.elements.price.addEventListener('input',update);update();
  form.elements.item_name.addEventListener('change',()=>{const p=products.find(x=>x.name.toLowerCase()===form.elements.item_name.value.trim().toLowerCase());if(p){form.elements.category.value=p.category;form.elements.unit.value=p.default_unit}});
 }
}
function showFieldError(name,message){const el=$('[data-error="'+name+'"]');if(el)el.textContent=message||'';const input=$('[name="'+name+'"]');if(input)input.classList.toggle('invalid',!!message)}
function validateForm(k,fd){
 const e={},req=(key,msg)=>{if(!String(fd[key]===undefined?'':fd[key]).trim())e[key]=msg},nn=(key,msg,min=0,whole=false)=>{const v=fd[key];if(v===''||v===undefined||!Number.isFinite(Number(v))||Number(v)<min||(whole&&!Number.isInteger(Number(v))))e[key]=msg};
 if(['harvest','sale','tray_sale','expense'].includes(k))req('date','Choose a valid date.');
 if(k==='harvest')SIZES.forEach(s=>nn('q_'+s,'Enter a whole quantity of 0 or more.',0,true));
 if(k==='sale'){req('buyer','Enter the buyer name.');req('item','Choose an egg size.');nn('quantity','Enter a whole egg quantity greater than zero.',1,true);nn('price','Enter a price greater than ₱0.',0.01)}
 if(k==='tray_sale'){req('buyer','Enter the buyer name.');req('item','Choose an egg size.');const full=Number(fd.full_tray_quantity);if(fd.full_tray_quantity===''||!Number.isFinite(full)||full<0||!Number.isInteger(full))e.full_tray_quantity='Enter a whole number of full trays (0 or more).';if((!Number.isFinite(full)||full===0)&&fd.include_half_tray!=='yes')e.full_tray_quantity='Enter at least one full tray or select the half-tray option.';if(Number.isFinite(full)&&(full>0||fd.include_half_tray==='yes')){const total=Math.max(0,full)*trayPrice(fd.item,1)+(fd.include_half_tray==='yes'?trayPrice(fd.item,0.5):0);if(total<=0)e.full_tray_quantity='Set a valid full-tray or half-tray price in Tray price settings.'}}
 if(k==='expense'){req('item_name','Enter an item name.');req('category','Choose a category.');nn('quantity','Quantity must be greater than zero.',0.000001);req('unit','Choose a unit.');nn('price','Enter a price greater than ₱0.',0.01)}
 if(k==='contact'){req('name','Enter the contact name.');req('role','Choose the contact type.');if(fd.email&&fd.email.trim()&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(fd.email))e.email='Enter a valid email address or leave blank.'}
 Object.keys(e).forEach(k=>showFieldError(k,e[k]));return e;
}

const LOCAL_KEY='eggharvest_hatchable_local_v1';
const LOCAL_SETTINGS_KEY='eggharvest_hatchable_settings_v1';
const LOCAL_AVATAR_KEY='eggharvest_hatchable_avatar_v1';
function saveLocal(){
 try{localStorage.setItem(LOCAL_KEY,JSON.stringify(records));localStorage.setItem(LOCAL_SETTINGS_KEY,JSON.stringify(settings));
 const names=new Map();records.filter(r=>r.kind==='expense').forEach(r=>{const d=r.data||{};if(d.item_name)names.set(String(d.item_name).toLowerCase(),{name:d.item_name,category:d.category||'Other',default_unit:d.unit||'piece'})});products=[...names.values()];localStorage.setItem('eggharvest_hatchable_products_v1',JSON.stringify(products));return true}
 catch(e){throw new Error('Hindi ma-save sa browser storage. Baka puno na ang storage. I-export muna ang records kung available.')}}
function loadLocal(){
 records=JSON.parse(localStorage.getItem(LOCAL_KEY)||'[]');settings=JSON.parse(localStorage.getItem(LOCAL_SETTINGS_KEY)||'{"tray_prices":{},"tray_capacity":30}');products=JSON.parse(localStorage.getItem('eggharvest_hatchable_products_v1')||'[]');
 if(!settings||typeof settings!=='object')settings={tray_prices:{},tray_capacity:30};if(!settings.tray_prices)settings.tray_prices={};if(!settings.tray_capacity)settings.tray_capacity=30;
}
function migrateOldLocalData(){
 if(localStorage.getItem(LOCAL_KEY))return;
 let old;try{old=JSON.parse(localStorage.getItem('eggharvest_local_v2')||'null')}catch(e){return}if(!old)return;
 const made=[];const add=(kind,data,id)=>made.push({id:String(id||Date.now()+Math.random()),kind,data,created_at:new Date().toISOString()});
 (old.harvest||[]).forEach(r=>{const d={date:r.date};SIZES.forEach(s=>{const oldSize=({'Pullets':'Pullets','Small':'Small','Medium':'Medium','Large':'Large','XL':'Extra Large','Jumbo':'Jumbo'})[s];d[s]=Number(r[s]??r[oldSize]??0)});d.total_eggs=SIZES.reduce((a,s)=>a+Number(d[s]||0),0);add('harvest',d,r.id)});
 (old.sales||[]).forEach(r=>{const item=({'Pullets':'Pullets','Small':'Small','Medium':'Medium','Large':'Large','XL':'XL','Jumbo':'Jumbo'})[r.size]||r.size;const tray=r.type==='tray';const qty=tray?(Number(r.fullTrays||0)*30+(r.halfTray?15:0)):Number(r.quantity||0);add('sale',{date:r.date,item,quantity:qty,price:qty?Number(r.total||0)/qty:0,total:Number(r.total||0),buyer:r.buyer||'',seller:r.seller||'No info yet',selling_method:tray?'tray':'individual',full_tray_quantity:Number(r.fullTrays||0),include_half_tray:!!r.halfTray,tray_quantity:Number(r.fullTrays||0)+(r.halfTray?.5:0),payment_status:r.paymentMethod==='cash'?'Paid':(Number(r.paid||0)>0?'Partial':'Unpaid'),amount_paid:Number(r.paid||0),note:r.notes||''},r.id)});
 (old.expenses||[]).forEach(r=>add('expense',{date:r.date,item_name:r.item||r.item_name||'',category:r.category||'Other',quantity:Number(r.quantity||1),unit:r.unit||'piece',price:Number(r.quantity?Number(r.amount||0)/Number(r.quantity):r.amount||0),amount:Number(r.amount||0),supplier:r.seller||r.supplier||'Not provided',note:r.notes||''},r.id));
 (old.contacts||[]).forEach(r=>add('contact',{name:r.name||'',role:r.type||r.role||'Buyer',phone:r.phone||'',email:r.email||'',address:r.address||'',notes:r.notes||''},r.id));
 records=made;settings={tray_prices:{},tray_capacity:30};SIZES.forEach(s=>{const os=({'Pullets':'Pullets','Small':'Small','Medium':'Medium','Large':'Large','XL':'XL','Jumbo':'Jumbo'})[s];settings.tray_prices[s]={full:Number(old.trayPrices?.[os]?.full||0),half:Number(old.trayPrices?.[os]?.half||0)}});saveLocal();
}

async function submitForm(ev){
 ev.preventDefault();if(busy)return;const form=ev.currentTarget;let k=form.dataset.kind;const fd=Object.fromEntries(new FormData(form).entries());
 document.querySelectorAll('[data-error]').forEach(x=>x.textContent='');document.querySelectorAll('.invalid').forEach(x=>x.classList.remove('invalid'));
 const errors=validateForm(k,fd);if(Object.keys(errors).length){const el=$('[name="'+Object.keys(errors)[0]+'"]');if(el)el.focus();return}
 let data={...(editing?editing.data:{}),...fd};
 if(k==='harvest'){SIZES.forEach(s=>{data[s]=Number(fd['q_'+s]);delete data['q_'+s]});data.total_eggs=SIZES.reduce((a,s)=>a+data[s],0)}
 if(k==='sale'){data.selling_method='individual';data.quantity=Number(fd.quantity);data.price=Number(fd.price);data.total=Math.round(data.quantity*data.price*100)/100;data.buyer=fd.buyer.trim();data.seller=fd.seller||'Owner';if(!data.harvest_id)delete data.harvest_id}
 if(k==='tray_sale'){const full=Math.max(0,Math.floor(Number(fd.full_tray_quantity))),half=fd.include_half_tray==='yes',capacity=num(settings.tray_capacity)||30,fullPrice=trayPrice(fd.item,1),halfPrice=trayPrice(fd.item,0.5),total=Math.round((full*fullPrice+(half?halfPrice:0))*100)/100,eggs=(full+(half?0.5:0))*capacity;data.selling_method='tray';data.full_tray_quantity=full;data.include_half_tray=half;data.full_tray_price=fullPrice;data.half_tray_price=halfPrice;data.tray_quantity=full+(half?0.5:0);data.unit_price_tray=total;data.tray_capacity=capacity;data.quantity=eggs;data.price=eggs>0?total/eggs:0;data.total=total;data.buyer=fd.buyer.trim();data.seller=fd.seller||'Owner';if(!data.harvest_id)delete data.harvest_id;k='sale'}
 if(k==='sale'){data.payment_status=fd.payment_status||'Not recorded';if(data.payment_status==='Paid')data.amount_paid=data.total;else if(data.payment_status==='Partial')data.amount_paid=Math.round(num(fd.amount_paid)*100)/100;else if(data.payment_status==='Unpaid')data.amount_paid=0;else delete data.amount_paid;}
   if(k==='expense'){data.quantity=Number(fd.quantity);data.price=Number(fd.price);data.amount=Math.round(data.quantity*data.price*100)/100;data.supplier=(fd.supplier||'').trim()||'Not provided';data.seller=data.supplier}
 if(k==='contact'){data.name=fd.name.trim()}
 const btn=$('#saveButton');busy=true;btn.disabled=true;btn.textContent='Saving…';
 try{const wasEditing=!!editing;if(editing){records=records.map(r=>String(r.id)===String(editing.id)?{...r,kind:k,data,updated_at:new Date().toISOString()}:r)}else{records.push({id:(crypto.randomUUID?crypto.randomUUID():String(Date.now()+Math.random())),kind:k,data,created_at:new Date().toISOString()})}saveLocal();closeModal();await loadData();toast(wasEditing?'Record updated successfully.':'Record saved successfully.')}catch(e){$('#formError').textContent=e.message||'Could not save the record.';$('#formError').classList.remove('hidden')}finally{busy=false;btn.disabled=false;btn.textContent='Save record'}
}
async function saveTrayPrices(ev){
 ev.preventDefault();const form=ev.currentTarget,prices={};for(const s of SIZES){prices[s]={full:Number(form.elements['full_'+s].value||0),half:Number(form.elements['half_'+s].value||0)};if(!Number.isFinite(prices[s].full)||prices[s].full<0||!Number.isFinite(prices[s].half)||prices[s].half<0){$('#priceSaveError').textContent='All prices must be zero or greater.';$('#priceSaveError').classList.remove('hidden');return}}
 const btn=$('#saveTrayPrices');btn.disabled=true;btn.textContent='Saving…';try{settings.tray_prices=prices;saveLocal();toast('Tray prices saved.');render()}catch(e){$('#priceSaveError').textContent=e.message||'Could not save prices.';$('#priceSaveError').classList.remove('hidden')}finally{btn.disabled=false;btn.textContent='Save tray prices'}
}
async function deleteRecord(id){const r=records.find(x=>String(x.id)===String(id));if(!r)return;if(!confirm('Delete this '+(r.kind==='sale'&&r.data.selling_method==='tray'?'tray sale':r.kind)+' record permanently? This cannot be undone.'))return;try{records=records.filter(x=>String(x.id)!==String(id));saveLocal();await loadData();toast('Record deleted. Totals and charts have been recalculated.')}catch(e){toast(e.message||'Could not delete record.')}}
function closeModal(){$('#modal').classList.add('hidden');editing=null;busy=false}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
async function loadData(){try{$('#app').innerHTML='<div class="loading">Loading saved farm records…</div>';loadLocal();render()}catch(e){$('#app').innerHTML='<div class="panel"><h3>Could not load farm records</h3><p class="stat-foot">'+esc(e.message||'Please refresh and try again.')+'</p><button class="secondary" id="retryLoad">Retry</button></div>';$('#retryLoad').onclick=loadData}}
$('#headerAdd').onclick=()=>openForm(({harvest:'harvest',expenses:'expense',contacts:'contact'})[view]||'sale');
