document.addEventListener('keydown',e=>{const card=e.target.closest('[data-stat-view]');if(card&&(e.key==='Enter'||e.key===' ')){e.preventDefault();setView(card.dataset.statView)}});
$('#closeModal').onclick=closeModal;$('#cancelModal').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});$('#recordForm').addEventListener('submit',submitForm);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').classList.contains('hidden'))closeModal();if(e.key==='Escape')setAccountMenu(false)});
function setAccountMenu(open){const box=$('#accountBox'),button=$('#profileButton');if(!box||!button)return;box.hidden=!open;button.setAttribute('aria-expanded',String(open));}
function paintAvatar(url){const img=$('#profileAvatar'),fallback=$('#profileFallback');if(url){img.src=url;img.hidden=false;fallback.hidden=true}else{img.removeAttribute('src');img.hidden=true;fallback.hidden=false}$('#removeAvatarButton').hidden=!customAvatar;}
function setAvatarMessage(message,error=false){const el=$('#avatarMessage');el.textContent=message;el.classList.toggle('error',error);}
async function resizeAvatar(file){if(!file||!/^image\/(jpeg|png|webp)$/.test(file.type))throw new Error('Choose a JPG, PNG, or WebP image.');if(file.size>8*1024*1024)throw new Error('Please choose an image smaller than 8 MB.');const source=URL.createObjectURL(file);try{return await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas'),scale=Math.min(1,320/Math.max(img.naturalWidth,img.naturalHeight));canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.78))};img.onerror=()=>reject(new Error('Could not read that image. Please choose another.'));img.src=source})}finally{URL.revokeObjectURL(source)}}
async function saveAvatar(value){const button=$('#changeAvatarButton'),remove=$('#removeAvatarButton');button.disabled=true;remove.disabled=true;try{customAvatar=value||null;if(value)localStorage.setItem(LOCAL_AVATAR_KEY,value);else localStorage.removeItem(LOCAL_AVATAR_KEY);paintAvatar(value||null);setAvatarMessage(value?'Profile picture updated in this browser.':'Profile picture reset to default.');toast(value?'Profile picture updated.':'Profile picture reset.')}catch(e){setAvatarMessage('Could not save profile picture in browser storage.',true)}finally{button.disabled=false;remove.disabled=false;$('#avatarFile').value=''}}
$('#profileButton').addEventListener('click',()=>setAccountMenu($('#accountBox').hidden));
$('#changeAvatarButton').addEventListener('click',()=>$('#avatarFile').click());
$('#avatarFile').addEventListener('change',async e=>{const file=e.target.files&&e.target.files[0];if(!file)return;try{await saveAvatar(await resizeAvatar(file))}catch(err){setAvatarMessage(err.message||'Could not process that image.',true);e.target.value=''}});
