$('#accountEmail').textContent='Local browser workspace';$('#accountRole').textContent='Saved only in this browser on this device';customAvatar=localStorage.getItem(LOCAL_AVATAR_KEY)||null;paintAvatar(customAvatar);setAvatarMessage('');
